DEFAULT_PUBLIC_KEY_PEM = b"""
-----BEGIN PUBLIC KEY-----
MCowBQYDK2VwAyEAnhfrubIeVcSD391rI6ClleZF7bC/m8CeKOORBozj3po=
-----END PUBLIC KEY-----
"""

# DEVELOPMENT OVERRIDE: If this is set, we bypass crypto check for "mock_key"
